CRASH_LOG_PATH = os.path.join(BASE, "crash.log")
_crash_seen = {}
def _log_crash(where, exc_type, exc, tb):
    """把异常写进 crash.log (主线程/后台线程/Tk 回调三路都往这汇): 打包成 EXE 后没有控制台,
    异常不落盘就永远查不到 (v1.4.18 的 F4 静默失败就是这么藏了很久)。同一错误 60 秒内只记一次, 防刷屏;
    文件超过约 1MB 时只留尾部。日志本身出错绝不能影响程序。"""
    try:
        import traceback as _tb
        text = "".join(_tb.format_exception(exc_type, exc, tb)) if exc_type else str(exc)
        key = (where, text.strip().splitlines()[-1] if text.strip() else "")
        now = time.time()
        if now - _crash_seen.get(key, 0) < 60: return
        _crash_seen[key] = now
        try:
            if os.path.exists(CRASH_LOG_PATH) and os.path.getsize(CRASH_LOG_PATH) > 1_000_000:
                with open(CRASH_LOG_PATH, encoding="utf-8", errors="replace") as _f: tail = _f.read()[-200_000:]
                _atomic_write(CRASH_LOG_PATH, tail)
        except Exception: pass
        with open(CRASH_LOG_PATH, "a", encoding="utf-8") as f:
            f.write(f"\n===== {time.strftime('%Y-%m-%d %H:%M:%S')} [{where}] =====\n{text}\n")
    except Exception: pass
def _install_crash_logging():
    """装三路异常钩子 + C 级崩溃记录 (faulthandler): sys 钩子管主线程未捕获异常,
    threading 钩子管后台线程 (翻译/下载/识别都在后台, 以前异常直接消失), faulthandler 管原生库硬崩溃。"""
    import threading
    def _sys_hook(exc_type, exc, tb):
        _log_crash("main", exc_type, exc, tb)
        sys.__excepthook__(exc_type, exc, tb)
    sys.excepthook = _sys_hook
    def _thr_hook(args):
        _log_crash(f"thread:{getattr(args.thread, 'name', '?')}", args.exc_type, args.exc_value, args.exc_traceback)
    threading.excepthook = _thr_hook
    try:
        import faulthandler
        _np = os.path.join(BASE, "crash_native.log")
        if os.path.exists(_np) and os.path.getsize(_np) > 2_000_000:  # 原生日志原先只追加无上限, 反复崩溃能无限涨: 启动时截断只留尾部
            with open(_np, encoding="utf-8", errors="replace") as _f: _tail = _f.read()[-200_000:]
            _atomic_write(_np, _tail)
        fh = open(_np, "a", encoding="utf-8")
        faulthandler.enable(file=fh)
        globals()["_faulthandler_file"] = fh  # 保住句柄别被回收
    except Exception: pass

def _atomic_write(path, text):
    """原子写: 先写临时文件, flush+fsync 落盘后再 os.replace 换名。直接覆盖写时若断电/崩溃, 文件会写一半损坏,
    记录和配置 (含翻译密钥) 就全丢了; 原子写保证磁盘上永远是完整的新版或旧版。fsync 不能省 (2026-11-27 审查):
    没有它, 断电/蓝屏时数据可能还停在系统缓存里, replace 完成了照样丢最后一次写。"""
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        f.write(text); f.flush(); os.fsync(f.fileno())
    os.replace(tmp, path)
    try:  # 目录项也刷一次, 保证改名本身落盘 (Windows 上目录 fsync 不可用, 失败就算了)
        dfd = os.open(os.path.dirname(os.path.abspath(path)), os.O_RDONLY)
        try: os.fsync(dfd)
        finally: os.close(dfd)
    except Exception: pass
def _ini_scalar(v):
    """配置值收成一行: 换行/制表/连续空白全压成单个空格。值里混进换行会把 Config.ini 写坏 —
    值中的一行 "Evil=1" 下次读取就变成一个真键 (注入/损坏双防), 所有落盘值先过这里。"""
    return " ".join(str(v).split())

def _migrate_old_data():
    """老数据搬移 (新目录还没有 Config.ini 时才搬, 已存在的文件不覆盖):
    ① 旧品牌数据目录 %APPDATA%\\SPST 与 %APPDATA%\\SnapPaste (这两个是被搬移的旧目录名, 历史引用, 不能改成 KIVO) ② 更早的老版本 (<=v1.4.4) 放在 EXE 旁的数据"""
    if not getattr(sys, "frozen", False) or os.path.abspath(BASE) == os.path.abspath(EXE_DIR): return
    if os.path.exists(os.path.join(BASE, "Config.ini")): return  # 新目录已有数据, 不再搬
    import shutil
    def _copy_from(src_dir):
        for rel in ("Config.ini", "records.json", "records.json.bak", "phrases.json", "phrases.json.bak", "ai_chats.json", "ai_chats.json.bak", "calc_history.json", "bookmarks.json", "bookmarks.json.bak", "browser_history.json", "browser_history.json.bak", "ding.wav",
                    os.path.join("Language", "Chinese.ini"), os.path.join("Language", "English.ini")):
            src, dst = os.path.join(src_dir, rel), os.path.join(BASE, rel)
            if os.path.exists(src) and not os.path.exists(dst):
                try: os.makedirs(os.path.dirname(dst), exist_ok=True); shutil.copy(src, dst)
                except Exception: pass
        old_shots, new_shots = os.path.join(src_dir, "shots"), os.path.join(BASE, "shots")
        if os.path.isdir(old_shots):
            try:
                os.makedirs(new_shots, exist_ok=True)
                for name in os.listdir(old_shots):
                    s, d = os.path.join(old_shots, name), os.path.join(new_shots, name)
                    if os.path.isfile(s) and not os.path.exists(d):
                        try: shutil.copy(s, d)
                        except Exception: pass
            except Exception: pass
    appdata = os.environ.get("APPDATA")
    if appdata:
        for legacy_name in ("SPST", "SnapPaste"):  # 旧品牌数据目录名 (历史引用, 故意保留旧名)
            old_base = os.path.join(appdata, legacy_name)
            if os.path.abspath(old_base) != os.path.abspath(BASE): _copy_from(old_base)
    _copy_from(EXE_DIR)

def _cleanup_legacy_browser_files():
    """v1.4.22 起内置浏览器已删除 (Jane 定版不好用): 把它留在数据目录的书签/历史/缓存删干净 (Jane 09:10 要求)。
    每次启动都扫一遍 (删不存在的文件零成本), 迁移搬进来的老文件也一并清掉 (本函数在迁移之后跑)。"""
    import shutil
    for name in ("bookmarks.json", "bookmarks.json.bak", "browser_history.json", "browser_history.json.bak",
                 "browser_host.json", "browser_cmd.json", "browser_state.json"):
        try: os.remove(os.path.join(BASE, name))
        except Exception: pass
    shutil.rmtree(os.path.join(BASE, "browser_profile"), ignore_errors=True)

def ensure_runtime_files():
    """EXE 首次运行: 先搬老数据 (EXE 旁 -> AppData), 再把内置默认文件释放到数据目录; 已存在的不覆盖"""
    import shutil
    _migrate_old_data()
    _cleanup_legacy_browser_files()
    for rel in ("Config.ini", "ding.wav", os.path.join("Language", "Chinese.ini"), os.path.join("Language", "English.ini")):
        src, dst = os.path.join(BUNDLE, rel), os.path.join(BASE, rel)
        if not os.path.exists(dst) and os.path.exists(src):
            try:
                os.makedirs(os.path.dirname(dst), exist_ok=True); shutil.copy(src, dst)
            except Exception: pass

# Win32 SendInput 结构: 必须带完整 union, 否则 sizeof(INPUT) 不是系统要求的 40 字节 (x64), 调用会被拒绝
class _KEYBDINPUT(ctypes.Structure):
    _fields_ = [("wVk", ctypes.c_ushort), ("wScan", ctypes.c_ushort), ("dwFlags", ctypes.c_uint32),
                ("time", ctypes.c_uint32), ("dwExtraInfo", ctypes.c_void_p)]
class _MOUSEINPUT(ctypes.Structure):
    _fields_ = [("dx", ctypes.c_int), ("dy", ctypes.c_int), ("mouseData", ctypes.c_uint32),
                ("dwFlags", ctypes.c_uint32), ("time", ctypes.c_uint32),
                ("dwExtraInfo", ctypes.c_void_p)]
class _HARDWAREINPUT(ctypes.Structure):
    _fields_ = [("uMsg", ctypes.c_uint32), ("wParamL", ctypes.c_ushort), ("wParamH", ctypes.c_ushort)]
class _INPUTUNION(ctypes.Union):
    _fields_ = [("mi", _MOUSEINPUT), ("ki", _KEYBDINPUT), ("hi", _HARDWAREINPUT)]
class _INPUT(ctypes.Structure):
    _fields_ = [("type", ctypes.c_uint32), ("u", _INPUTUNION)]

def enable_hidpi():
    if sys.platform == "win32":
        try: ctypes.windll.shcore.SetProcessDpiAwareness(1)
        except Exception:
            try: ctypes.windll.user32.SetProcessDPIAware()
            except Exception: pass

def _rrect_pts(w, h, r):
    """圆角矩形点列: 四角弧线采样, Canvas smooth 后是真圆角"""
    import math
    r = max(2, min(r, w // 2, h // 2))
    pts = []
    for cx, cy, a0 in ((w - r, r, -90), (w - r, h - r, 0), (r, h - r, 90), (r, r, 180)):
        for a in range(a0, a0 + 91, 15):
            rad = math.radians(a)
            pts += [cx + r * math.cos(rad), cy + r * math.sin(rad)]
    return pts


class _PillButton(tk.Canvas):
    """圆角胶囊按钮 (画布绘制): primary=品牌蓝实心白字 / soft=浅灰底深字 / outline=白底蓝字浅蓝边。
    支持 config(text=) 改字并自动改宽 (主窗口截图按钮的热键标注刷新靠它), 也支持 cget("text")"""
    _VARIANTS = {
        "primary": ("#287FD1", "#287FD1", "#FFFFFF", "#4A97DC"),
        "soft": ("#EAF0F8", "#EAF0F8", "#2A3440", "#DCE8F7"),
        "outline": ("#FFFFFF", "#BCD6FF", "#1F6AB3", "#EBF2FF"),
        "tool": ("#FFFFFF", "#E1E7F0", "#2A3440", "#EDF3FF"),
    }

    def __init__(self, parent, text="", command=None, variant="soft", font=None, bg="#FFFFFF", height=30, pad_x=14, image=None, radius=None):
        from tkinter import font as tkfont
        self._font_tuple = font or ("TkDefaultFont", 10)
        self._measure = tkfont.Font(font=self._font_tuple)
        self._text = text; self._command = command; self._variant = variant
        self._h = height; self._pad_x = pad_x
        self._radius = radius if radius is not None else height // 2
        self._iw = (image.width() + 5) if image is not None else 0
        w = self._measure.measure(text) + pad_x * 2 + self._iw
        super().__init__(parent, width=w, height=height, highlightthickness=0, background=bg, cursor="hand2", borderwidth=0)
        fill, outline, fg, _hov = self._VARIANTS.get(variant, self._VARIANTS["soft"])
        self._fill, self._outline = fill, outline
        self._poly = self.create_polygon(_rrect_pts(w, height, self._radius), smooth=True, fill=fill, outline=outline)
        if image is not None:
            self._iid = self.create_image(pad_x + (self._iw - 5) // 2, height // 2, image=image)
        else:
            self._iid = None
        self._tid = self.create_text(pad_x + self._iw + self._measure.measure(text) // 2, height // 2, text=text, font=self._font_tuple, fill=fg)
        self.bind("<Button-1>", lambda e: self._command() if self._command else None)
        self.bind("<Enter>", self._on_hover)
        self.bind("<Leave>", self._on_leave)

    def invoke(self):
        if self._command: self._command()

    def _on_hover(self, _e=None):
        hov = self._VARIANTS.get(self._variant, self._VARIANTS["soft"])[3]
        if self._variant in ("outline", "tool"):
            self.itemconfigure(self._poly, fill=hov)
        else:
            self.itemconfigure(self._poly, fill=hov, outline=hov)

    def _on_leave(self, _e=None):
        self.itemconfigure(self._poly, fill=self._fill, outline=self._outline)

    def configure(self, cnf=None, **kw):
        if cnf is None and not kw:
            return super().configure()
        if cnf and isinstance(cnf, dict): kw.update(cnf)
        if "text" in kw:
            self._text = kw.pop("text")
            w = self._measure.measure(self._text) + self._pad_x * 2 + self._iw
            super().configure(width=w)
            self.coords(self._poly, *_rrect_pts(w, self._h, self._radius))
            self.coords(self._tid, self._pad_x + self._iw + self._measure.measure(self._text) // 2, self._h // 2)
            self.itemconfigure(self._tid, text=self._text)
        if "command" in kw: self._command = kw.pop("command")
        if kw: super().configure(**kw)
    config = configure

    def cget(self, key):
        if key == "text": return self._text
        return super().cget(key)


class _NavItem(tk.Canvas):
    """左侧边栏导航项: 圆角胶囊高亮 (选中浅蓝/悬停更浅) + 糖果图标 + 文字 (Jane 2026-11-27 边栏版)"""
    def __init__(self, parent, text="", command=None, font=None, bg="#FFFFFF", image=None):
        super().__init__(parent, width=188, height=40, background=bg, highlightthickness=0, bd=0, cursor="hand2")
        self._text = text; self._command = command; self._font = font; self._image = image
        self._selected = False; self._hover = False
        self.bind("<Button-1>", lambda _e: self.invoke())
        self.bind("<Enter>", lambda _e: self._set_hover(True))
        self.bind("<Leave>", lambda _e: self._set_hover(False))
        self._draw()
    def _draw(self):
        self.delete("all")
        fill = "#D9E9F8" if self._selected else ("#EFF5FC" if self._hover else None)
        if fill: self.create_polygon(_rrect_pts(188, 40, 10), fill=fill, outline=fill, smooth=True)
        if self._image is not None: self.create_image(14, 20, image=self._image, anchor="w")
        self.create_text(52, 21, text=self._text, anchor="w", font=self._font,
                         fill="#1F6AB3" if self._selected else "#1C2634")
    def _set_hover(self, on):
        self._hover = bool(on); self._draw()
    def set_selected(self, on):
        self._selected = bool(on); self._draw()
    def invoke(self):
        if self._command is not None: self._command()
    def cget(self, key):
        if key == "text": return self._text
        return super().cget(key)


class App(tk.Tk):
    def __init__(self):
        super().__init__()
        ensure_runtime_files()
        enable_hidpi()
        self.title(f"{APP_NAME} v{VERSION}")
        try:  # 窗口图标 (标题栏/任务栏) 用内嵌的 KIVO 图标
            self._icon_photo = tk.PhotoImage(data=_ICON_PNG_B64); self.iconphoto(True, self._icon_photo)
        except Exception: pass
        self.geometry("680x580"); self.minsize(600, 500)  # v1.3: 内容区变高, 旧 460 高会裁掉底部状态栏
        self.records = []          # [{"text": str, "locked": bool}]
        self._visible = []         # 列表框行号 -> records 下标 (搜索过滤时两者不一致, 必须映射)
        self._ui_queue = queue.Queue()  # 全局热键在 keyboard 线程触发, 只能排队回主线程执行 Tk 操作
        self._pins = []                # 当前所有贴图窗口 (供 关闭全部/隐藏全部/穿透 等动作统一管理)
        self._last_closed_pin = None   # 最近关闭的那张贴图的图片, 供「恢复上次关闭的贴图」
        self._pins_clickthrough = False
        self._snip_finish_mode = None  # 本次截图的特殊完成方式 (如 "copy" = 框选完直接复制, 不停留标注)
        self._tray = None              # 系统托盘图标 (pystray), 没装该库时为 None, 点 X 直接退出
        self._tray_notified = False    # 「已隐藏到托盘」的气泡只提示一次
        self.paste_index = 0
        self._hk_handles = []      # keyboard 包返回的句柄, 改热键时注销旧的
        self._oc_handle = None     # 全局切换热键的句柄 (单独管理, 关掉全部热键时它要留着)
        self._hk_enabled = True
        self._mini_win = None; self._mini_after = None
        self._tk_sequences = []    # 窗口内绑定的序列, 改热键时解绑旧的
        self.cfg = self.load_config()
        self._load_lang()
        self._apply_theme()
        self.after(2500, self._ocr_warmup)  # 空闲预热 OCR 引擎: 首次建引擎加载三模型要数秒, 别让第一次走 OCR 的 F4 干等
        self._splash = self._make_splash()  # 启动页 (仅打包版/显式开启): 构建期间盖住空白主窗
        self.build_ui()
        self._fit_window_to_content()
        self.load_records()
        self.load_phrases()
        self.refresh_list()
        self.refresh_shots()
        self.apply_hotkeys()
        self.apply_autorun()
        self._setup_tray()
        if self.cfg.get("Config", "MiniFormSet", fallback="0") == "1": self.after(300, self.show_mini)  # 常显模式: 启动即显示迷你窗口
        self.after(15, self._poll_ui_queue)  # 15ms 轮询: 热键动作最多等 15ms 就执行 (旧 60ms 每次按键先白等)
        self.protocol("WM_DELETE_WINDOW", self.on_close)
        self.bind("<Map>", self._on_main_map)  # 主窗口从托盘恢复显示时, 补刷隐藏期间标脏的列表
        self.bind("<Escape>", lambda e: self.on_close())  # Esc 关闭主窗口 (同点 X: 隐藏到托盘)
        if getattr(self, "_splash", None) is not None: self.after(650, self._close_splash)
    def _make_splash(self):
        """启动页 (2026-11-27 品牌升级): KIVO 标 + 启沃智能工作台 + 口号; 只在打包版 (frozen) 或 KIVO_SPLASH=1 时出现, 测试环境不出现"""
        if not (getattr(sys, "frozen", False) or os.environ.get("KIVO_SPLASH") == "1"): return None
        try:
            self.withdraw()
            sp = tk.Toplevel(self); sp.overrideredirect(True)
            try: sp.attributes("-topmost", True)
            except Exception: pass
            card = tk.Frame(sp, background="#FFFFFF", highlightthickness=1, highlightbackground="#D8E4F2"); card.pack()
            try:
                img = tk.PhotoImage(data=_ICON_PNG_B64).subsample(3, 3)
                lb = tk.Label(card, image=img, background="#FFFFFF"); lb.image = img; lb.pack(padx=64, pady=(26, 6))
            except Exception: pass
            tk.Label(card, text="KIVO", font=self._ui_font(20, True), background="#FFFFFF", foreground="#1C2634").pack()
            tk.Label(card, text=self.t("splash_sub", "启沃智能工作台"), font=self._ui_font(10), background="#FFFFFF", foreground="#7A8699").pack(pady=(2, 0))
            tk.Label(card, text=self.t("about_slogan", "让效率, 自然发生 · Make Work Flow"), font=self._ui_font(9), background="#FFFFFF", foreground="#287FD1").pack(pady=(10, 2))
            tk.Label(card, text=self.t("splash_loading", "正在启动…"), font=self._ui_font(9), background="#FFFFFF", foreground="#7A8699").pack(pady=(0, 22))
            sp.update_idletasks()
            w, h = sp.winfo_reqwidth(), sp.winfo_reqheight()
            sp.geometry(f"+{(sp.winfo_screenwidth() - w) // 2}+{(sp.winfo_screenheight() - h) // 2}")
            sp.update()
            return sp
        except Exception:
            try: self.deiconify()
            except Exception: pass
            return None

    def _close_splash(self):
        sp = getattr(self, "_splash", None); self._splash = None
        try: self.deiconify()
        except Exception: pass
        if sp is not None:
            try: sp.destroy()
            except Exception: pass

    def _nav_show(self, key, title=None):
        """边栏导航高亮 + 内容区标题同步 (各视图入口调用; 导航未建好时静默)"""
        items = getattr(self, "_nav_items", None)
        if not items: return
        for k, it in items.items():
            try: it.set_selected(k == key)
            except Exception: pass
        lb = getattr(self, "_page_title", None)
        if lb is not None:
            try: lb.configure(text=title or getattr(self, "_nav_titles", {}).get(key, ""))
            except Exception: pass

    def _fit_window_to_content(self):
        # 按内容实际需要的尺寸定窗口大小: 写死的 680x580 在高缩放 (125%/150%) 屏幕上装不下全部功能,
        # 底部截图按钮和状态栏会被裁掉, 要手动往下拉高才看得全 (真机反馈)。打开即按内容定高;
        # 但最小高度不能锁死到内容高度 (旧做法): 那样窗口没法缩小、最大化也像失灵, 不像普通软件 —— Jane 2026-11-25 指出后改。
        try:
            self.update_idletasks()
            req_w, req_h = self.winfo_reqwidth(), self.winfo_reqheight()
            sw, sh = self.winfo_screenwidth(), self.winfo_screenheight()
            w = min(max(680, req_w), sw)
            h = min(req_h, max(500, sh - 50))
            self.geometry(f"{w}x{h}")
            min_h = 600 if sh >= 700 else 500  # 边栏版: 边栏底部有「设置」入口, 窗口缩得太矮会被裁掉; 高屏保底 600, 矮屏仍 500
            self.minsize(min(620, w), min(min_h, h))  # 最小高度只保底: 窗口可自由缩放/最大化, 标题栏 ─ ▢ ✕ 都是系统标准按钮
            self.resizable(True, True)
        except Exception: pass
    def report_callback_exception(self, exc, val, tb):
        _log_crash("tk-callback", exc, val, tb)  # 只记录不弹窗: 回调异常不该把软件带崩, 但必须留痕可查
    def _poll_ui_queue(self):
        try:
            while True:
                fn = self._ui_queue.get_nowait()
                try: fn()
                except Exception as e: _log_crash("ui-queue", type(e), e, e.__traceback__)
        except queue.Empty: pass
        try: self.after(15, self._poll_ui_queue)
        except tk.TclError: pass

    def _on_main_map(self, e=None):
        if e is not None and e.widget is not self: return
        if getattr(self, "_list_dirty", False) and not getattr(self, "_map_refresh_pending", False):
            # 补刷推迟 50ms 再做: 在 <Map> 里同步重建上千行列表会堵住窗口恢复后的第一帧绘制,
            # Windows 等不到绘制就先给黑帧 (Jane 2026-11-25 真机报「点任务栏打开软件闪黑」)。
            # 先让窗口按现有内容画出来, 列表随后跟上; 挂起标志防连发 Map 重复排队。
            self._map_refresh_pending = True
            self.after(50, self._map_refresh)
    def _map_refresh(self):
        self._map_refresh_pending = False
        if getattr(self, "_list_dirty", False) and self.winfo_viewable(): self.refresh_list()
    def _focus_in_input(self):
        """键盘焦点是不是在输入控件里 (搜索框/间隔/分隔符/下拉框等): 在的话按键先归输入框,
        根窗口上的 Delete/单字热键绑定不许抢 —— 否则在搜索框里删字会把选中的记录删掉。
        (不能看事件的 widget: 事件沿 bindtags 传播到根绑定时, widget 已变成根窗口本身。)"""
        try:
            w = self.focus_get()
            return w is not None and w.winfo_class() in ("Entry", "TEntry", "TCombobox", "Text", "Spinbox", "TSpinbox")
        except Exception: return False
    @staticmethod
    def _is_text_key(e):
        """这个按键在输入框里是不是打字/编辑用的 (无 Ctrl/Alt 的字母数字空格标点、退格、Delete):
        功能键和带 Ctrl/Alt 的组合键不算 —— 它们在输入框里获得焦点时也应照常触发热键。"""
        if e.state & 0x4 or e.state & 0x8 or e.state & 0x20000: return False  # 带 Ctrl/Alt
        ks = e.keysym or ""
        return len(ks) == 1 or ks in ("space", "BackSpace", "Delete", "comma", "period", "minus", "equal",
                                      "slash", "backslash", "semicolon", "apostrophe", "grave",
                                      "bracketleft", "bracketright")
    # ---------- config (兼容原版字段) ----------
    def load_config(self):
        hk_defaults = {f"HotKey{i}": "无" for i in range(13)}; hk_defaults.update(DEFAULT_HOTKEYS)
        defaults_dict = {"Config": {"SleepTime": "80", "WaveSet": "0", "AutoRun": "0", "Language": "Chinese", "PasteEnter": "0", "PasteRemove": "1",
                                    "MiniFormTime": "5", "MiniFormSet": "0", "AddChar": "1", "LetterSet": "0", "ShowHotKey": "F2"},
                         "HotKey": hk_defaults, "Snip": dict(DEFAULT_SNIP_KEYS),
                         "OCHotKey": {"HotKey": "无", "OCAutoSet": "0"}}
        def _fresh():
            # strict=False: 老版本 ini 里万一有重复段, 取最后的值而不是整份配置静默回退默认; interpolation=None: 用户填的分隔符/路径/网址里带 % 时默认插值会让 set/get 直接抛错, 本软件不用插值语法
            c = configparser.ConfigParser(strict=False, interpolation=None)
            c.read_dict(defaults_dict); return c
        if not os.path.exists(CONFIG_PATH): return _fresh()
        # 原版是 GBK, 新版是 UTF-8: 依次尝试; 每轮用全新 parser——同一 parser 第一轮解析到一半抛错时,
        # 已读入的段会残留, 第二轮在其上合并出混合配置 (2026-11-25 审查发现)
        for enc in ("utf-8-sig", "gbk"):
            c = _fresh()
            try: c.read(CONFIG_PATH, encoding=enc); return c
            except Exception: continue
        return _fresh()
    def _load_lang(self):
        """语言: 读 Language/<Language>.ini 的 [UI] 段 (沿用原版的语言文件机制); 缺键时回退到代码里的中文原文"""
        self.lang = self.cfg.get("Config", "Language", fallback="Chinese").strip() or "Chinese"
        self._strings = {}
        # 语言文件是程序自带资源而不是用户数据: 优先读 EXE 内置的那份 (BUNDLE), 升级后新文案立刻生效;
        # 早期版本把语言文件释放到数据目录 (AppData) 且从不更新, 旧文件会一直盖住新文案 —— 真机上已经去掉的
        # 「(合并自 Snipaste 核心功能, 需 Pillow)」还一直显示就是这个原因; 数据目录里的只作兜底。
        p = os.path.join(BUNDLE, "Language", f"{self.lang}.ini")
        if not os.path.exists(p): p = os.path.join(BASE, "Language", f"{self.lang}.ini")
        if os.path.exists(p):
            lp = configparser.ConfigParser(strict=False, interpolation=None)
            for enc in ("utf-8-sig", "gbk"):
                lp = configparser.ConfigParser(strict=False, interpolation=None)  # 每轮全新: 防半解析残留污染下一轮 (同 load_config)
                try: lp.read(p, encoding=enc); break
                except Exception: lp = configparser.ConfigParser(strict=False, interpolation=None); continue
            if lp.has_section("UI"): self._strings = dict(lp.items("UI"))
    def t(self, key, zh):
        return self._strings.get(key, zh).replace("\\n", "\n")  # ini 里多行文案写成 \n 转义, 这里还原
    def save_config(self):
        # 保存配置绝不能把程序搞崩: 整个过程兜底; 但失败不能静默 — 磁盘满/文件被占用时用户以为存上了,
        # 重启才发现设置回滚且无从排查 (千问 2026-11-27 指出)。记进 crash.log, _log_crash 自带 60 秒去重不刷屏。
        try: self._save_config_inner()
        except Exception: _log_crash("save-config", *sys.exc_info())
    def _save_config_inner(self):
        # v1.1 修复: 原地更新已有 key, 保住 Config.ini 里的注释和排版 (旧版 configparser.write 会全抹掉)
        for _sec in self.cfg.sections():  # 落盘前把每个值收成一行: 防粘贴进来的值带换行把 ini 结构写坏
            for _k, _v in list(self.cfg.items(_sec)):
                if _v is not None and _ini_scalar(_v) != _v: self.cfg.set(_sec, _k, _ini_scalar(_v))
        if not os.path.exists(CONFIG_PATH):
            import io
            buf = io.StringIO(); self.cfg.write(buf); _atomic_write(CONFIG_PATH, buf.getvalue())
            return
        raw = open(CONFIG_PATH, "rb").read()
        for enc in ("utf-8-sig", "gbk"):  # 用户手动改过 ini 时可能是 GBK, 读不出就别硬读 (旧版直接抛异常, 设置一保存就报错)
            try: lines = raw.decode(enc).splitlines(); break
            except Exception: lines = []
        else: lines = []
        pending = {(sec, k.lower()): v for sec in self.cfg.sections() for k, v in self.cfg.items(sec)}
        out, cur = [], None
        for line in lines:
            stripped = line.strip()
            if stripped.startswith("[") and stripped.endswith("]"):
                cur = stripped[1:-1].strip()
            elif cur and "=" in line and not stripped.startswith((";", "#")):
                key = line.split("=", 1)[0].strip().lower()
                if (cur, key) in pending:
                    line = f"{line.split('=', 1)[0].strip()}={pending.pop((cur, key))}"
            out.append(line)
        # 文件里没有的键: 段已存在就插入该段末尾; 段不存在才在文件尾新建段。
        # (旧写法一律在文件尾追加 [段], 会造出重复段, 下次读取 DuplicateSectionError 后静默丢配置)
        by_sec = {}
        known_case = {k.lower(): k for k in list(DEFAULT_HOTKEYS) + list(DEFAULT_SNIP_KEYS) +
                      ["SleepTime", "WaveSet", "WaveFile", "AutoRun", "AutoSet", "MiniFormTime", "MiniFormSet", "Language", "PasteEnter", "PasteRemove",
                       "SplitPos", "AddChar", "LetterSet", "HotKey", "OCAutoSet", "Form1XY", "Form2XY", "UIDetect", "HistoryMax", "DelaySeconds",
                       "Separator", "CustomSep", "SplitChar", "RegexSel", "CaseSel", "TransTarget", "ShowHotKey", "HistorySave", "DownloadDir", "DownloadAsk", "ClockCities", "ConvCopyMode",
                       "Service", "BaiduAppId", "BaiduKey", "YoudaoAppId", "YoudaoSecret", "GoogleKey", "TransCompare", "TTUseAI", "MiniTrans", "CopyTrans",
                       "ReplyKey", "ApiKey", "Model", "BaseUrl",
                       "ZhipuKey", "ZhipuModel", "ZhipuBase", "BailianKey", "BailianModel", "BailianBase",
                       "SiliconflowKey", "SiliconflowModel", "SiliconflowBase", "CustomKey", "CustomModel", "CustomBase",
                       "RouteChat", "RouteVision", "RouteReply", "RouteText", "RouteAnnotate", "Thinking",
                       "OpenaiKey", "OpenaiModel", "OpenaiBase", "GeminiKey", "GeminiModel", "GeminiBase",
                       "ClaudeKey", "ClaudeModel", "ClaudeBase", "DeepseekKey", "DeepseekModel", "DeepseekBase",
                       "MoonshotKey", "MoonshotModel", "MoonshotBase", "VolcengineKey", "VolcengineModel", "VolcengineBase",
                       "HunyuanKey", "HunyuanModel", "HunyuanBase", "QianfanKey", "QianfanModel", "QianfanBase",
                       "XaiKey", "XaiModel", "XaiBase", "DotsKey", "DotsModel", "DotsBase",
                       "OllamaKey", "OllamaModel", "OllamaBase"]}
        for (sec, k), v in pending.items(): by_sec.setdefault(sec, []).append((known_case.get(k, k), v))
        for sec, items in by_sec.items():
            headers = [i for i, ln in enumerate(out) if ln.strip().lower() == f"[{sec.lower()}]"]
            if headers:
                nxt = next((i for i in range(headers[0] + 1, len(out)) if out[i].strip().startswith("[")), len(out))
                out[nxt:nxt] = [f"{k}={v}" for k, v in items]
            else:
                out += [f"[{sec}]"] + [f"{k}={v}" for k, v in items]
        _atomic_write(CONFIG_PATH, "\n".join(out) + "\n")
    @property
    def sleep_ms(self):
        try: return max(10, self.cfg.getint("Config", "SleepTime", fallback=80))
        except Exception: return 80  # 间隔被写成非数字 (旧版托盘保存没校验) 时别让软件启动就崩

