    def _ui_font(self, size=10, bold=False):
        fam = "Microsoft YaHei UI" if sys.platform == "win32" else "Noto Sans CJK SC"
        return (fam, size, "bold") if bold else (fam, size)
    def _btn_icon(self, name):
        """按钮小图标 (懒加载缓存 PhotoImage; 拿不到就返回 None, 按钮退回纯文字)"""
        cache = getattr(self, "_btn_icon_cache", None)
        if cache is None: cache = self._btn_icon_cache = {}
        if name not in cache:
            try: cache[name] = tk.PhotoImage(data=_BTN_ICONS_B64[name])
            except Exception: cache[name] = None
        return cache[name]
    _TOOL_TINTS = {"copy": ("#1D7FE0", "#DCEEFF"), "phrases": ("#DE8A00", "#FDEEC9"), "translate": ("#1F9D66", "#D8F3E3"),
                   "ai": ("#7C5CFC", "#E7E1FF"), "fx": ("#0CA6A0", "#D2F1EF"), "clock": ("#5B6EE1", "#E0E4FC"),
                   "calc": ("#EE5B7F", "#FDE0E8"), "download": ("#F06423", "#FEE3D3"), "gear": ("#5B7A99", "#E2EBF3"), "star": ("#E8A13A", "#FCEFD2")}

    def _tool_icon(self, name):
        """工具栏彩色图标: 浅糖果色圆角方块底 + 同色系 glyph (Jane 2026-11-27 美化: 界面别太单调)。
        拿不到原图或画失败就退回普通图标, 按钮照常能用。"""
        cache = getattr(self, "_tool_icon_cache", None)
        if cache is None: cache = self._tool_icon_cache = {}
        if name in cache: return cache[name]
        img = None
        try:
            import base64, io
            from PIL import Image as _PI, ImageDraw as _PD, ImageTk as _PT
            fg, bgc = self._TOOL_TINTS.get(name, ("#33506E", "#E8EEF5"))
            raw = _PI.open(io.BytesIO(base64.b64decode(_BTN_ICONS_B64[name]))).convert("RGBA")
            S = 56
            chip = _PI.new("RGBA", (S, S), (0, 0, 0, 0))
            _PD.Draw(chip).rounded_rectangle([1, 1, S - 2, S - 2], radius=15, fill=bgc)
            glyph = _PI.new("RGBA", raw.size, fg); glyph.putalpha(raw.getchannel("A"))
            chip.alpha_composite(glyph.resize((30, 30), _PI.LANCZOS), ((S - 30) // 2, (S - 30) // 2))
            img = _PT.PhotoImage(chip.resize((28, 28), _PI.LANCZOS))
        except Exception:
            img = None
        if img is None: img = self._btn_icon(name)
        cache[name] = img
        return img

