        for i, (rk, lk, lz) in enumerate(route_defs):
            ttk.Label(rframe, text=self.t(lk, lz) + ":").grid(row=i, column=0, sticky="e", padx=6, pady=3)
            cur_r = (self.cfg.get("AI", rk, fallback="") or "").strip()
