    # ---------- AI 功能: 看图翻译 / 智能回复 ----------
    def ai_translate_image(self, img, route="vision"):
        """AI 看图翻译: 视觉模型直接看整张图翻译 (理解版面和上下文, 艺术字/复杂排版比 OCR 逐行翻得准); 后台线程跑"""
        if not self._ai_ready(route): return
        if getattr(self, "_ai_busy", False):  # 上一张图还在等模型回复: 别重复发请求、叠结果窗
            self.status.set(self.t("ai_busy", "AI 正在处理上一张图, 稍等它回复完再试")); return
        self._ai_busy = True
        self.status.set(self.t("ai_img_working", "AI 正在看图翻译..."))
        import threading
        def work():
            try:
                res = self._ai_chat_image(img, self._AI_TRANSLATE_PROMPT, temperature=0.3, route=route)  # 翻译要稳, 温度调低少发挥
                self._ui_queue.put(lambda: (setattr(self, "_ai_busy", False), self._show_ai_translate(img, res)))
            except Exception as e:
                msg = str(e)
                self._ui_queue.put(lambda: (setattr(self, "_ai_busy", False), self.status.set(self.t("ai_img_failed", "AI 看图翻译失败")), messagebox.showinfo(self.t("ai_img_title", "AI 看图翻译"), msg)))
        threading.Thread(target=work, daemon=True).start()
    def _show_ai_translate(self, img, text):
        self.status.set(self.t("ai_img_done", "AI 看图翻译完成"))
        win = tk.Toplevel(self); win.title(self.t("ai_img_title", "AI 看图翻译")); win.attributes("-topmost", True)
        win.bind("<Escape>", lambda e: win.destroy())
        ow, oh = img.size; scale = min(1.0, 560 / ow, 300 / oh)
        if scale < 1.0: disp = img.resize((max(1, int(ow * scale)), max(1, int(oh * scale))), Image.LANCZOS)
        else: disp = img
        ph = ImageTk.PhotoImage(disp); win._photo = ph
        tk.Label(win, image=ph).pack(padx=8, pady=(8, 4))
        bhold = tk.Frame(win, background=win.cget("background")); bhold.pack(fill="both", expand=True, padx=8, pady=4)
        self._rounded_backing(bhold, radius=8, fill=self.UI_SURFACE, bg=win.cget("background"))
        box = tk.Text(bhold, wrap="word", width=64, height=10, font=self._ui_font(10), bg=self.UI_SURFACE, fg=self.UI_TEXT,
                      relief="flat", bd=0, highlightthickness=0, padx=8, pady=6, insertbackground=self.UI_ACCENT)
        box.pack(fill="both", expand=True, padx=5, pady=5); box.insert("1.0", text or self.t("ai_no_result", "(模型没有返回译文)"))
        bar = ttk.Frame(win); bar.pack(fill="x", padx=8, pady=6)
        copy_btn = ttk.Button(bar, text=self.t("ai_copy_trans", "复制译文"), style="Accent.TButton")
        def do_copy():
            self.clip_set(box.get("1.0", "end").strip()); copy_btn.config(text=self.t("cmn_copied", "已复制 ✓"))
            win.after(1200, lambda: win.winfo_exists() and copy_btn.config(text=self.t("ai_copy_trans", "复制译文")))
        copy_btn.config(command=do_copy); copy_btn.pack(side="left", padx=2)
        def to_queue():
            added = 0
            for line in box.get("1.0", "end").splitlines():
                if line.strip(): self.add_record(line, save=False); added += 1
            if added: self.save_records()
            self.refresh_list(); self.status.set(f"{self.t('ai_queue_done', '译文已加入文字队列, 按 F7 逐条粘贴')} ({added})")
        ttk.Button(bar, text=self.t("ai_to_queue", "加入文字队列"), command=to_queue).pack(side="left", padx=2)
        ttk.Button(bar, text=self.t("cmn_close", "关闭"), command=win.destroy).pack(side="right", padx=2)
    @staticmethod
    def _parse_replies(text):
        """把模型回复拆成候选列表: 去掉行首序号/符号, 最多取 3 条; 拆不出就整段当 1 条。纯逻辑, 可单测。"""
        out = []
        for ln in (text or "").splitlines():
            s = re.sub(r"^\s*(\d+\s*[.、)）:：]|[-•·])\s*", "", ln).strip()
            if s: out.append(s)
        return out[:3] if out else []
    def snip_ai_translate(self):
        """看图翻译 (截图工具栏「AI翻译」/贴图右键菜单入口): 先查 key, 再框选一张图 -> AI 直接读图翻译"""
        if not self._ai_ready("vision"): return
        self._snip_finish_mode = "ai"; self.snip_region()

    def snip_reply(self):
        """智能回复: 框选聊天区域 -> AI 读懂对话给 3 条候选 -> 点一条直接粘进刚才的聊天窗口"""
        if not self._ai_ready("reply"): return  # 先查 key: 没填就别让用户白框选一趟, 截完才弹窗问
        self._snip_finish_mode = "reply"; self.snip_region()
    def ai_smart_reply(self, img):
        if not self._ai_ready("reply"): return
        if getattr(self, "_ai_busy", False):
            self.status.set(self.t("ai_busy", "AI 正在处理上一张图, 稍等它回复完再试")); return
        self._ai_busy = True
        self.status.set(self.t("ai_reply_working", "AI 正在读对话、想回复..."))
        import threading
        def work():
            try:
                res = self._ai_chat_image(img, self._AI_REPLY_PROMPT, route="reply")
                cands = self._parse_replies(res) or ([res] if res else [])
                self._ui_queue.put(lambda: (setattr(self, "_ai_busy", False), self._show_reply_candidates(img, cands)))
            except Exception as e:
                msg = str(e)
                self._ui_queue.put(lambda: (setattr(self, "_ai_busy", False), self.status.set(self.t("ai_reply_failed", "智能回复失败")), messagebox.showinfo(self.t("ai_reply_title", "智能回复"), msg)))
        threading.Thread(target=work, daemon=True).start()
    def _show_reply_candidates(self, img, cands):
        self.status.set(self.t("ai_reply_hint_status", "智能回复: 点一条即可粘贴到刚才的软件"))
        if not cands:
            messagebox.showinfo(self.t("ai_reply_title", "智能回复"), self.t("ai_reply_none", "模型没给出候选回复, 换个更完整的对话截图再试。")); return
        win = tk.Toplevel(self); win.title(self.t("ai_reply_win_title", "智能回复 — 点一条直接粘贴")); win.minsize(540, 0); win.attributes("-topmost", True)  # 高度不写死: 候选条数不定, 让窗口按内容自适应 (写死高度会把按钮挤出窗外)
        win.bind("<Escape>", lambda e: win.destroy())
        ttk.Label(win, text=self.t("ai_reply_win_hint", "AI 按对话语境想了这几条, 点「粘贴」直接发到刚才的聊天窗口:"), style="Muted.TLabel").pack(anchor="w", padx=10, pady=(10, 4))
        def paste_it(text):
            win.destroy()
            if self.winfo_viewable():
                if self._tray is not None: self._hide_to_tray()
                else: self.withdraw()
            self.after(180, lambda: self._paste_text(text))  # 与常用语库同一套: 先让焦点回到刚才的软件再粘
        for i, c in enumerate(cands, 1):
            row = tk.Frame(win, background=self.UI_BG); row.pack(fill="x", padx=10, pady=4)
            self._rounded_backing(row, radius=8, fill=self.UI_SURFACE, bg=self.UI_BG)
            tk.Label(row, text=f"{i}. {c}", wraplength=400, background=self.UI_SURFACE, foreground=self.UI_TEXT,
                     font=self._ui_font(10), justify="left").pack(side="left", fill="x", expand=True, padx=(10, 4), pady=7)
            ttk.Button(row, text=self.t("cmn_paste", "粘贴"), style="Accent.TButton", command=lambda t=c: paste_it(t)).pack(side="right", padx=(2, 8), pady=6)
            ttk.Button(row, text=self.t("cmn_copy", "复制"), command=lambda t=c: self.clip_set(t)).pack(side="right", padx=2, pady=6)
        bar = ttk.Frame(win); bar.pack(fill="x", padx=10, pady=(6, 10))
        def again():
            win.destroy(); self.ai_smart_reply(img)
        ttk.Button(bar, text=self.t("ai_another", "换一批"), command=again).pack(side="left", padx=2)
        ttk.Button(bar, text=self.t("cmn_close", "关闭"), command=win.destroy).pack(side="right", padx=2)
    def _load_ai_chats(self):
        """读 AI 最近对话存档 (ai_chats.json, 带 .bak 兜底): 坏条目逐条丢弃, 不让一份坏档拖垮面板"""
        for p in (AI_CHATS_PATH, AI_CHATS_PATH + ".bak"):
            try:
                if os.path.exists(p):
                    data = json.loads(open(p, encoding="utf-8").read())
                    if isinstance(data, list):
                        out = []
                        for c in data:
                            if isinstance(c, dict) and isinstance(c.get("messages"), list):
                                msgs = []
                                for m in c["messages"][-200:]:
                                    if not (isinstance(m, dict) and m.get("role") in ("user", "assistant")
                                            and isinstance(m.get("content"), str)):
                                        continue
                                    item = {"role": m["role"], "content": m["content"]}
                                    if isinstance(m.get("image_path"), str):
                                        item["image_path"] = m["image_path"]
                                    msgs.append(item)
                                if msgs: out.append({"id": c.get("id"), "title": str(c.get("title") or "新对话"), "updated": c.get("updated") or 0, "pin": 1 if c.get("pin") else 0, "messages": msgs})
                        return out
            except Exception: continue
        return []

    def _store_ai_chats(self):
        try:
            text = json.dumps(self._ai_chats, ensure_ascii=False)
            _atomic_write(AI_CHATS_PATH, text)
            try: _atomic_write(AI_CHATS_PATH + ".bak", text)
            except Exception: pass
        except Exception: pass

    def _persist_chat(self, hist, cid):
        """把一段对话历史写入存档并落盘, 返回它的 id (新建时生成)。当前对话和「已切走的对话」都走这里, 不会串话"""
        if not hist: return cid
        entry = next((c for c in self._ai_chats if c.get("id") == cid), None)
        if entry is None:
            cid = int(time.time() * 1000)
            first = next((m["content"] for m in hist if m["role"] == "user"), "新对话")
            entry = {"id": cid, "title": first.replace("\n", " ")[:18], "updated": 0, "messages": []}
            self._ai_chats.insert(0, entry)
        entry["messages"] = [dict(m) for m in hist][-200:]  # 单个对话最多存最近 200 条: 防长年累月攒到上千条, 打开时整表渲染会卡 (发给 AI 的上下文只用最近 20 条, 截掉老的无影响)
        entry["updated"] = time.time()
        self._ai_chats.sort(key=lambda c: (0 if c.get("pin") else 1, -(c.get("updated") or 0)))  # 置顶的永远排前面 (仿 GPT), 组内按最近更新
        del self._ai_chats[30:]
        self._store_ai_chats()
        return cid

    def _save_current_chat(self):
        """把当前对话增量存进最近列表 (发送后/回复后各存一次, 关软件也不丢): 标题取第一条用户消息, 最多留 30 个对话"""
        hist = getattr(self, "_ai_chat_history", [])
        if not hist: return
        self._ai_chat_id = self._persist_chat(hist, getattr(self, "_ai_chat_id", None))
        if hasattr(self, "_refresh_recent"): self._refresh_recent()

