    @staticmethod
    def _fx_fetch_rates():
        """拉美元基准的全部汇率: 返回 (rates, 更新时间UTC字符串)。免费接口, 数据每日更新 (面板上会标明更新时间)"""
        import urllib.request
        req = urllib.request.Request("https://open.er-api.com/v6/latest/USD", headers={"User-Agent": "KIVO"})
        with urllib.request.urlopen(req, timeout=20) as r:
            data = json.loads(r.read().decode("utf-8"))
        if data.get("result") != "success" or not isinstance(data.get("rates"), dict):
            raise RuntimeError("汇率接口返回异常")
        return data["rates"], data.get("time_last_update_utc", "")

    def open_fx(self):
        self._nav_show("fx")
        """货币汇率 (工具栏按钮): 与 AI 面板一样盖住主窗口下半区, 点「复制粘贴」或面板里「返回」回去"""
        self._show_fx_panel()

    def _show_fx_panel(self):
        self._texttrans_on_hide()
        if getattr(self, "_fx_panel", None) is None:
            self._build_fx_panel()
        try: self._body.pack_forget()
        except Exception: pass
        if getattr(self, "_ai_panel", None) is not None:
            try: self._ai_panel.pack_forget()
            except Exception: pass
        self._ai_view_on = False
        self._wheel_bind(False)
        if getattr(self, "_calc_panel", None) is not None:
            try: self._calc_panel.pack_forget()
            except Exception: pass
        if getattr(self, "_phrases_panel", None) is not None:
            try: self._phrases_panel.pack_forget()
            except Exception: pass
        if getattr(self, "_clock_panel", None) is not None:
            try: self._clock_panel.pack_forget()
            except Exception: pass
        if getattr(self, "_dl_panel", None) is not None:
            try: self._dl_panel.pack_forget()
            except Exception: pass
        self._calc_bind(False)
        self._forget_aux_panels()
        self._fx_panel.pack(fill="both", expand=True, before=self._status_sep)
        if getattr(self, "_fx_reload", None) is not None and (
                not getattr(self, "_fx_rates", None) or time.time() - getattr(self, "_fx_fetched_at", 0) > 3600):
            self._fx_reload()  # 第一次打开自动拉一次; 之后数据超过 1 小时再打开也自动刷新 (免费源每日更新, 不必勤拉)

    def _rounded_backing(self, frame, radius=10, fill="#FFFFFF", bg=None, border=None):
        """给方角卡片垫一层圆角底 (Jane 2026-11-27 全系统去直角): Canvas 铺满 frame 底层画圆角面+描边,
        frame 背景须先改成与外部一致, 内容内缩 >=5px 躲开圆角; 尺寸变化自动重绘"""
        if bg is None: bg = self.UI_BG
        cv = tk.Canvas(frame, background=bg, highlightthickness=0, borderwidth=0)
        cv.place(x=0, y=0, relwidth=1, relheight=1)
        def draw(_e=None):
            w, h = cv.winfo_width(), cv.winfo_height()
            if w < 12 or h < 12: return
            cv.delete("rr")
            pid = cv.create_polygon(_rrect_pts(w - 2, h - 2, radius), smooth=True, fill=fill, outline=border or self.UI_BORDER, tags="rr")
            cv.move(pid, 1, 1)
        cv.bind("<Configure>", draw)
        return cv
    def _panel_title(self, head, text, icon=None, bg=None):
        """面板标题 (Jane 2026-11-27 排版美化): 热门软件式的彩色小图标 + 粗体标题, 柔和统一"""
        bg = bg or self.UI_BG
        if icon:
            try:
                img = self._tool_icon(icon)
                lb = tk.Label(head, image=img, background=bg); lb.image = img
                lb.pack(side="left", padx=(0, 7))
            except Exception: pass
        tk.Label(head, text=text, font=self._ui_font(12, True), background=bg, foreground=self.UI_TEXT).pack(side="left")

    def _set_section(self, parent, title):
        """系统设置分区: 圆角描边卡 + 内置标题 (代替方角 LabelFrame), 返回内容区"""
        outer = tk.Frame(parent, background=self.UI_BG)
        outer.pack(fill="x", pady=(8, 2))
        self._rounded_backing(outer, radius=10, fill=self.UI_BG)
        _trow = tk.Frame(outer, background=self.UI_BG); _trow.pack(anchor="w", fill="x", padx=12, pady=(8, 2))
        tk.Frame(_trow, background=self.UI_ACCENT, width=4, height=14).pack(side="left", pady=1)
        tk.Label(_trow, text=title, font=self._ui_font(10, True), background=self.UI_BG, foreground="#2F4B73").pack(side="left", padx=(6, 0))
        inner = tk.Frame(outer, background=self.UI_BG)
        inner.pack(fill="x", padx=12, pady=(0, 10))
        return inner
    def _fx_flag_img(self, code):
        """币种国旗小图 (Jane 2026-11-27 要求汇率表加各国国旗): PIL 按各国旗主要特征简笔绘制, 缓存复用。"""
        cache = getattr(self, "_fx_flag_cache", None)
        if cache is None: cache = self._fx_flag_cache = {}
        if code in cache: return cache[code]
        from PIL import Image as _Im, ImageDraw as _IDr
        import math as _m
        Wd, Ht = 96, 64
        img = _Im.new("RGBA", (Wd, Ht), (255, 255, 255, 255))
        d = _IDr.Draw(img)
        def rect(x0, y0, x1, y1, c): d.rectangle([x0, y0, x1, y1], fill=c)
        def hstripes(spec):
            tot = sum(w for _, w in spec); y = 0.0
            for c, w in spec:
                y2 = y + Ht * w / tot; rect(0, y, Wd, y2 + 1, c); y = y2
        def vstripes(spec):
            tot = sum(w for _, w in spec); x = 0.0
            for c, w in spec:
                x2 = x + Wd * w / tot; rect(x, 0, x2 + 1, Ht, c); x = x2
        def disc(cx, cy, r, c, outline=None, width=2): d.ellipse([cx - r, cy - r, cx + r, cy + r], fill=c, outline=outline, width=width)
        def star(cx, cy, r, c, n=5, ratio=0.45, rot=-90):
            pts = []
            for i in range(2 * n):
                rr = r if i % 2 == 0 else r * ratio
                a = _m.radians(rot + i * 180 / n)
                pts.append((cx + rr * _m.cos(a), cy + rr * _m.sin(a)))
            d.polygon(pts, fill=c)
        def crescent(cx, cy, r, c, bg, off=0.38):
            disc(cx, cy, r, c); disc(cx + r * off, cy, r * 0.86, bg)
        def cross(vx, hw, c, vy=0, vh=None, bg=None, bw=0):
            if bg: rect(vx - bw, 0, vx + hw + bw, Ht, bg); rect(0, vy - bw, Wd, vy + vh + bw, bg)
            rect(vx, 0, vx + hw, Ht, c); rect(0, vy, Wd, vy + vh, c)
        def union(x0, y0, w, h):
            rect(x0, y0, x0 + w, y0 + h, "#012169")
            d.line([x0, y0, x0 + w, y0 + h], fill="#FFFFFF", width=max(2, int(h * 0.20)))
            d.line([x0 + w, y0, x0, y0 + h], fill="#FFFFFF", width=max(2, int(h * 0.20)))
            d.line([x0, y0, x0 + w, y0 + h], fill="#C8102E", width=max(1, int(h * 0.07)))
            d.line([x0 + w, y0, x0, y0 + h], fill="#C8102E", width=max(1, int(h * 0.07)))
            rect(x0 + w * 0.36, y0, x0 + w * 0.64, y0 + h, "#FFFFFF")
            rect(x0, y0 + h * 0.36, x0 + w, y0 + h * 0.64, "#FFFFFF")
            rect(x0 + w * 0.42, y0, x0 + w * 0.58, y0 + h, "#C8102E")
            rect(x0, y0 + h * 0.42, x0 + w, y0 + h * 0.58, "#C8102E")
        RED, YEL, WHT = "#DE2910", "#FFDE00", "#FFFFFF"
        fns = {
            "USD": lambda: (hstripes([("#B22234", 1), (WHT, 1)] * 4), rect(0, 0, 46, 34, "#3C3B6E"),
                            [disc(8 + (i % 4) * 11, 7 + (i // 4) * 9, 2.2, WHT) for i in range(12)]),
            "CNY": lambda: (rect(0, 0, Wd, Ht, RED), star(20, 18, 11, YEL), star(38, 8, 4, YEL), star(44, 16, 4, YEL), star(44, 26, 4, YEL), star(38, 34, 4, YEL)),
            "HKD": lambda: (rect(0, 0, Wd, Ht, "#E2231A"),
                            [d.ellipse([48 - 7 - 13 * _m.cos(_m.radians(72 * i)), 32 - 7 - 13 * _m.sin(_m.radians(72 * i)),
                                        48 + 7 - 13 * _m.cos(_m.radians(72 * i)), 32 + 7 - 13 * _m.sin(_m.radians(72 * i))], fill=WHT) for i in range(5)],
                            disc(48, 32, 4, "#E2231A")),
            "EUR": lambda: (rect(0, 0, Wd, Ht, "#039"),
                            [star(48 + 20 * _m.cos(_m.radians(30 * i)), 32 + 20 * _m.sin(_m.radians(30 * i)), 4.5, "#FC0") for i in range(12)]),
            "GBP": lambda: union(0, 0, Wd, Ht),
            "JPY": lambda: (rect(0, 0, Wd, Ht, WHT), disc(48, 32, 13, "#BC002D")),
            "KRW": lambda: (rect(0, 0, Wd, Ht, WHT), disc(48, 32, 15, "#CD2E3A"),
                            d.pieslice([33, 32, 63, 62], start=0, end=180, fill="#0047A0"),
                            disc(40.5, 32, 7.5, "#CD2E3A"), disc(55.5, 32, 7.5, "#0047A0"),
                            [rect(x, y, x + 10, y + 3, "#000") for x, y in ((8, 6), (78, 6), (8, 52), (78, 52))],
                            [rect(x, y + 5, x + 10, y + 8, "#000") for x, y in ((8, 6), (78, 6), (8, 52), (78, 52))]),
            "TWD": lambda: (rect(0, 0, Wd, Ht, "#FE0000"), rect(0, 0, 48, 32, "#000095"), disc(24, 16, 8, WHT),
                            [star(24 + 11 * _m.cos(_m.radians(30 * i)), 16 + 11 * _m.sin(_m.radians(30 * i)), 2.6, WHT, n=3, ratio=0.6) for i in range(12)]),
            "MOP": lambda: (rect(0, 0, Wd, Ht, "#067662"), star(48, 14, 5, YEL),
                            d.arc([30, 18, 66, 52], start=180, end=360, fill=YEL, width=4),
                            d.arc([38, 26, 58, 52], start=180, end=360, fill=YEL, width=4), rect(28, 50, 68, 54, YEL)),
            "AUD": lambda: (rect(0, 0, Wd, Ht, "#00247D"), union(0, 0, 48, 32), star(24, 46, 7, WHT, n=7, ratio=0.55),
                            disc(70, 14, 3, WHT), disc(80, 26, 3, WHT), disc(66, 38, 3, WHT), disc(76, 48, 3, WHT), disc(84, 56, 2.4, WHT)),
            "CAD": lambda: (rect(0, 0, Wd, Ht, WHT), rect(0, 0, 24, Ht, "#FF0000"), rect(72, 0, Wd, Ht, "#FF0000"),
                            d.polygon([(48, 10), (52, 20), (58, 17), (55, 26), (62, 26), (56, 33), (60, 38), (52, 36), (52, 46), (44, 46),
                                       (44, 36), (36, 38), (40, 33), (34, 26), (41, 26), (38, 17), (44, 20)], fill="#FF0000")),
            "CHF": lambda: (rect(0, 0, Wd, Ht, "#FF0000"), rect(40, 14, 56, 50, WHT), rect(29, 24, 67, 40, WHT)),
            "SGD": lambda: (hstripes([("#EF3340", 1), (WHT, 1)]), crescent(20, 16, 10, WHT, "#EF3340"),
                            disc(34, 8, 2, WHT), disc(40, 13, 2, WHT), disc(34, 18, 2, WHT), disc(28, 13, 2, WHT), disc(37, 22, 2, WHT)),
            "NZD": lambda: (rect(0, 0, Wd, Ht, "#00247D"), union(0, 0, 48, 32),
                            star(70, 14, 4, "#CC142B", ratio=0.5), star(78, 28, 4, "#CC142B", ratio=0.5), star(68, 42, 4, "#CC142B", ratio=0.5), star(80, 54, 3.4, "#CC142B", ratio=0.5)),
            "THB": lambda: hstripes([("#A51931", 1), ("#F4F5F8", 1), ("#2D2A4A", 2), ("#F4F5F8", 1), ("#A51931", 1)]),
            "MYR": lambda: (hstripes([("#CC0001", 1), (WHT, 1)] * 4), rect(0, 0, 50, 37, "#010066"),
                            crescent(18, 18, 12, "#FC0", "#010066"), star(38, 18, 9, "#FC0", n=14, ratio=0.62)),
            "IDR": lambda: hstripes([("#E70011", 1), (WHT, 1)]),
            "PHP": lambda: (hstripes([("#0038A8", 1), ("#CE1126", 1)]),
                            d.polygon([(0, 0), (38, 32), (0, 64)], fill=WHT), disc(13, 32, 6, "#FCD116"),
                            star(6, 8, 3, "#FCD116"), star(6, 56, 3, "#FCD116"), star(28, 32, 3, "#FCD116")),
            "VND": lambda: (rect(0, 0, Wd, Ht, "#DA251D"), star(48, 32, 13, "#FF0")),
            "INR": lambda: (hstripes([("#FF9933", 1), (WHT, 1), ("#138808", 1)]), disc(48, 32, 9, None, outline="#000080", width=3), disc(48, 32, 2, "#000080")),
            "AED": lambda: (hstripes([("#00732F", 1), (WHT, 1), ("#000000", 1)]), rect(0, 0, 26, Ht, "#FF0000")),
            "SAR": lambda: (rect(0, 0, Wd, Ht, "#165D31"), rect(18, 24, 78, 28, WHT), rect(14, 40, 82, 44, WHT),
                            d.polygon([(82, 40), (88, 42), (82, 44)], fill=WHT)),
            "RUB": lambda: hstripes([(WHT, 1), ("#0039A6", 1), ("#D52B1E", 1)]),
            "BRL": lambda: (rect(0, 0, Wd, Ht, "#009C3B"), d.polygon([(48, 6), (88, 32), (48, 58), (8, 32)], fill="#FFDF00"),
                            disc(48, 32, 13, "#002776"), d.arc([28, 20, 68, 46], start=200, end=320, fill=WHT, width=3),
                            disc(40, 28, 1.8, WHT), disc(52, 34, 1.8, WHT), disc(46, 38, 1.5, WHT)),
            "MXN": lambda: (vstripes([("#006847", 1), (WHT, 1), ("#CE1126", 1)]), disc(48, 30, 8, "#B5893C"), disc(48, 40, 5, "#006847")),
            "ZAR": lambda: (rect(0, 0, Wd, Ht, "#007749"),
                            d.polygon([(0, 0), (Wd, 0), (Wd, 22), (38, 32), (Wd, 42), (Wd, Ht), (0, Ht)], fill=WHT),
                            d.polygon([(0, 4), (Wd, 4), (Wd, 24), (40, 32), (Wd, 40), (Wd, 60), (0, 60)], fill="#001489"),
                            d.polygon([(0, 0), (Wd, 0), (Wd, 20), (44, 29), (0, 29)], fill="#E03C31"),
                            d.polygon([(0, 35), (44, 35), (Wd, 44), (Wd, Ht), (0, Ht)], fill="#001489"),
                            d.polygon([(0, 14), (30, 32), (0, 50)], fill="#FFB612"),
                            d.polygon([(0, 19), (24, 32), (0, 45)], fill="#000000")),
            "TRY": lambda: (rect(0, 0, Wd, Ht, "#E30A17"), crescent(38, 32, 16, WHT, "#E30A17"), star(62, 32, 8, WHT)),
            "SEK": lambda: (rect(0, 0, Wd, Ht, "#006AA7"), cross(26, 12, "#FECC00", vy=26, vh=12)),
            "NOK": lambda: (rect(0, 0, Wd, Ht, "#BA0C2F"), cross(26, 16, "#00285E", vy=24, vh=16, bg=WHT, bw=4)),
            "DKK": lambda: (rect(0, 0, Wd, Ht, "#C8102E"), cross(26, 12, WHT, vy=26, vh=12)),
            "PLN": lambda: hstripes([(WHT, 1), ("#DC143C", 1)]),
        }
        fn = fns.get(code)
        if fn:
            try: fn()
            except Exception: pass
        else:
            rect(0, 0, Wd, Ht, "#8A97A5")
        mask = _Im.new("L", (Wd, Ht), 0)
        _IDr.Draw(mask).rounded_rectangle([0, 0, Wd - 1, Ht - 1], radius=12, fill=255)
        img.putalpha(mask)
        d = _IDr.Draw(img)
        d.rounded_rectangle([1, 1, Wd - 2, Ht - 2], radius=11, outline=(160, 175, 190, 255), width=2)
        photo = ImageTk.PhotoImage(img.resize((32, 22), _Im.LANCZOS))
        cache[code] = photo
        return photo
    def _build_fx_panel(self):
        panel = tk.Frame(self._content, background=self.UI_BG); self._fx_panel = panel
        W = "#FFFFFF"
        state = {"loading": False}
        head = tk.Frame(panel, background=self.UI_BG); head.pack(fill="x", padx=14, pady=(10, 4))
        self._panel_title(head, self.t("fx_rates", "汇率换算"), "fx")
        upd_var = tk.StringVar()
        tk.Label(head, textvariable=upd_var, font=self._ui_font(9), background=self.UI_BG, foreground=self.UI_MUTED).pack(side="left", padx=8)
        back = tk.Label(head, text=self.t("cmn_back", "返回"), font=self._ui_font(9), background=self.UI_BG, foreground="#5B6B7C", cursor="hand2")
        back.pack(side="right")
        back.bind("<Button-1>", lambda e: self._show_main_view())
        back.bind("<Enter>", lambda e: back.configure(foreground=self.UI_ACCENT))
        back.bind("<Leave>", lambda e: back.configure(foreground="#5B6B7C"))
        refresh_btn = ttk.Button(head, text=self.t("fx_refresh", "刷新"), command=lambda: reload())
        refresh_btn.pack(side="right", padx=(0, 10))
        status_var = tk.StringVar(value=self.t("fx_fetching", "正在获取最新汇率…"))
        # ---- 换算卡 ----
        card = tk.Frame(panel, background=self.UI_BG)
        self._rounded_backing(card)
        card.pack(fill="x", padx=12, pady=(6, 0))
        tk.Label(card, text=self.t("fx_convert", "货币换算"), font=self._ui_font(10, True), background=W, foreground=self.UI_TEXT).pack(anchor="w", padx=12, pady=(9, 0))
        row = tk.Frame(card, background=W); row.pack(fill="x", padx=12, pady=(6, 2))
        names = [f"{c} {self._fx_name(c, n)}" for c, n in self._FX_CURRENCIES]
        amt_var = tk.StringVar(value="100")
        ttk.Entry(row, textvariable=amt_var, width=12).pack(side="left")
        from_flag = tk.Label(row, background=W); from_flag.pack(side="left", padx=(10, 0))
        from_var = tk.StringVar(value=f"USD {self._fx_name('USD', '美元')}")
        to_var = tk.StringVar(value=f"CNY {self._fx_name('CNY', '人民币')}")
        ttk.Combobox(row, textvariable=from_var, values=names, width=13, state="readonly").pack(side="left", padx=(8, 0))
        swap_btn = ttk.Button(row, text="⇄", width=3)
        swap_btn.pack(side="left", padx=6)
        def swap():
            a, b = from_var.get(), to_var.get()
            from_var.set(b); to_var.set(a)
        swap_btn.configure(command=swap)
        to_flag = tk.Label(row, background=W); to_flag.pack(side="left", padx=(6, 0))
        ttk.Combobox(row, textvariable=to_var, values=names, width=13, state="readonly").pack(side="left")
        result_var = tk.StringVar(value="")
        tk.Label(row, textvariable=result_var, font=self._ui_font(13, True), background=W, foreground=self.UI_ACCENT).pack(side="left", padx=12)
        hint_var = tk.StringVar()
        tk.Label(card, textvariable=hint_var, font=self._ui_font(9), background=W, foreground=self.UI_MUTED).pack(anchor="w", padx=12, pady=(0, 9))
        # ---- 汇率表卡 ----
        card2 = tk.Frame(panel, background=self.UI_BG)
        self._rounded_backing(card2)
        card2.pack(fill="both", expand=True, padx=12, pady=(10, 0))
        trow = tk.Frame(card2, background=W); trow.pack(fill="x", padx=12, pady=(9, 4))
        tk.Label(trow, text=self.t("fx_table", "各币种汇率"), font=self._ui_font(10, True), background=W, foreground=self.UI_TEXT).pack(side="left")
        base_var = tk.StringVar(value=f"USD {self._fx_name('USD', '美元')}")
        ttk.Label(trow, text=self.t("fx_base", "基准:"), font=self._ui_font(9), background=W, foreground=self.UI_MUTED).pack(side="left", padx=(14, 2))
        base_flag = tk.Label(trow, background=W); base_flag.pack(side="left", padx=(4, 0))
        ttk.Combobox(trow, textvariable=base_var, values=names, width=13, state="readonly").pack(side="left")
        mid = tk.Frame(card2, background=W); mid.pack(fill="both", expand=True, padx=9, pady=(0, 9))
        _fst = ttk.Style()
        _fst.configure("Fx.Treeview", rowheight=27, font=self._ui_font(10))
        _fst.configure("Fx.Treeview.Heading", font=self._ui_font(10, True))
        tree = ttk.Treeview(mid, columns=("name", "code", "rate"), show="tree headings", selectmode="browse", style="Fx.Treeview")
        tree.column("#0", width=48, stretch=False); tree.heading("#0", text="")
        tree.heading("name", text=self.t("fx_col_name", "货币")); tree.heading("code", text=self.t("fx_col_code", "代码")); tree.heading("rate", text=self.t("fx_col_rate", "汇率"))
        tree.column("name", width=160, anchor="w", stretch=False); tree.column("code", width=80, anchor="center", stretch=False)
        tree.column("rate", anchor="e")
        tree.pack(side="left", fill="both", expand=True)
        tsb = ttk.Scrollbar(mid, command=tree.yview); tsb.pack(side="left", fill="y")
        tree.config(yscrollcommand=tsb.set)
        tree.tag_configure("odd", background=self.UI_STRIPE)
        tk.Label(panel, textvariable=status_var, font=self._ui_font(9), background=self.UI_BG, foreground=self.UI_MUTED).pack(anchor="w", padx=14, pady=(6, 8))
        def fmt(v):
            if v >= 100: return f"{v:,.2f}"
            if v >= 1: return f"{v:,.4f}"
            return f"{v:.6f}"
        def code_of(s):
            return (s or "").split(" ")[0]
        def fill_table():
            rates = getattr(self, "_fx_rates", None)
            tree.delete(*tree.get_children())
            if not rates: return
            base = code_of(base_var.get())
            if base not in rates: return
            for i, (code, name) in enumerate(self._FX_CURRENCIES):
                if code in rates:
                    tree.insert("", "end", image=self._fx_flag_img(code), values=(self._fx_name(code, name), code, fmt(rates[code] / rates[base])), tags=("odd",) if i % 2 else ())
        def convert():
            rates = getattr(self, "_fx_rates", None)
            if not rates: return
            try: amt = float((amt_var.get() or "").strip())
            except Exception:
                result_var.set(""); hint_var.set(self.t("fx_amount_hint", "金额填数字")); return
            fr, to = code_of(from_var.get()), code_of(to_var.get())
            if fr not in rates or to not in rates: return
            res = amt * rates[to] / rates[fr]
            result_var.set(f"= {res:,.2f} {to}")
            hint_var.set(f"1 {fr} = {fmt(rates[to] / rates[fr])} {to}")
        def reload():
            if state["loading"]: return
            state["loading"] = True
            refresh_btn.configure(state="disabled")
            status_var.set(self.t("fx_fetching", "正在获取最新汇率…"))
            import threading
            def work():
                try:
                    rates, upd = self._fx_fetch_rates()
                    def done():
                        state["loading"] = False
                        self._fx_rates = rates
                        self._fx_fetched_at = time.time()
                        if not panel.winfo_exists(): return
                        refresh_btn.configure(state="normal")
                        upd_var.set(f"{self.t('fx_updated', '更新时间')}: {upd}" if upd else "")
                        status_var.set(self.t("fx_source", "数据来源: open.er-api.com (免费接口, 每日更新)"))
                        fill_table(); convert()
                    self._ui_queue.put(done)
                except Exception as e:
                    msg = str(e)
                    def fail():
                        state["loading"] = False
                        if not panel.winfo_exists(): return
                        refresh_btn.configure(state="normal")
                        status_var.set(f"{self.t('fx_failed', '获取汇率失败')}: {msg}")
                    self._ui_queue.put(fail)
            threading.Thread(target=work, daemon=True).start()
        self._fx_reload = reload
        self._fx_convert = convert
        amt_var.trace_add("write", lambda *a: convert())
        from_var.trace_add("write", lambda *a: convert())
        to_var.trace_add("write", lambda *a: convert())
        base_var.trace_add("write", lambda *a: fill_table())
        def upd_flags(*a):
            try:
                from_flag.configure(image=self._fx_flag_img(code_of(from_var.get())))
                to_flag.configure(image=self._fx_flag_img(code_of(to_var.get())))
                base_flag.configure(image=self._fx_flag_img(code_of(base_var.get())))
            except Exception: pass
        from_var.trace_add("write", upd_flags); to_var.trace_add("write", upd_flags); base_var.trace_add("write", upd_flags)
        upd_flags()

    # ---------- 计算器 (标准四则运算, 面板式盖住下半区; 支持键盘输入) ----------
    def open_calc(self):
        self._nav_show("calc")
        """计算器 (工具栏按钮): 盖住主窗口下半区, 点「复制粘贴」或面板里「返回」回去"""
        self._show_calc_panel()

    def _calc_bind(self, on):
        h = getattr(self, "_calc_on_key", None)
        if h is None: return
        try:
            if on: self.bind_all("<KeyPress>", h)
            else: self.unbind_all("<KeyPress>")
        except Exception: pass

    def _show_calc_panel(self):
        self._texttrans_on_hide()
        if getattr(self, "_calc_panel", None) is None:
            self._build_calc_panel()
        try: self._body.pack_forget()
        except Exception: pass
        for attr in ("_ai_panel", "_fx_panel", "_phrases_panel", "_clock_panel", "_dl_panel"):
            p = getattr(self, attr, None)
            if p is not None:
                try: p.pack_forget()
                except Exception: pass
        self._ai_view_on = False
        self._wheel_bind(False)
        self._forget_aux_panels()
        self._calc_panel.pack(fill="both", expand=True, before=self._status_sep)
        self._calc_bind(True)

    def _build_calc_panel(self):
        panel = tk.Frame(self._content, background=self.UI_BG); self._calc_panel = panel
        W = "#FFFFFF"
        head = tk.Frame(panel, background=self.UI_BG); head.pack(fill="x", padx=14, pady=(10, 4))
        self._panel_title(head, self.t("calculator", "计算器"), "calc")
        back = tk.Label(head, text=self.t("cmn_back", "返回"), font=self._ui_font(9), background=self.UI_BG, foreground="#5B6B7C", cursor="hand2")
        back.pack(side="right")
        back.bind("<Button-1>", lambda e: self._show_main_view())
        back.bind("<Enter>", lambda e: back.configure(foreground=self.UI_ACCENT))
        back.bind("<Leave>", lambda e: back.configure(foreground="#5B6B7C"))
        body = tk.Frame(panel, background=self.UI_BG); body.pack(fill="both", expand=True)
        card = tk.Frame(body, background=self.UI_BG)
        self._rounded_backing(card)
        card.place(relx=0.5, rely=0.5, anchor="center")  # Jane 2026-11-27: 计算器放在面板正中间 (窗口缩放自动跟着居中)
        disp_var = tk.StringVar(value="0")
        trail_var = tk.StringVar(value="")
        tk.Label(card, textvariable=trail_var, font=self._ui_font(14), background=W, foreground=self.UI_MUTED, anchor="e").pack(fill="x", padx=22, pady=(18, 0))
        tk.Label(card, textvariable=disp_var, font=self._ui_font(40, True), background=W, foreground=self.UI_TEXT, anchor="e").pack(fill="x", padx=22, pady=(0, 12))
        st = {"acc": None, "op": None, "fresh": True}
        ERR = self.t("calc_error", "错误")  # 错误态判断统一用这份 (显示也是它): 旧版判断写死中文, 英文模式显示 Error 后判断永不成立、状态错乱 (审查发现)
        def fmt(v):
            if v != v or v in (float("inf"), float("-inf")): return self.t("calc_error", "错误")
            if abs(v - round(v)) < 1e-12 and abs(v) < 1e16: return str(int(round(v)))
            return f"{v:.10f}".rstrip("0").rstrip(".") or "0"
        def cur():
            try: return float(disp_var.get())
            except Exception: return 0.0
        def apply(a, o, b):
            if o == "+": return a + b
            if o == "-": return a - b
            if o == "×": return a * b
            if o == "÷":
                if b == 0: raise ZeroDivisionError
                return a / b
            return b
        def show_error():
            disp_var.set(self.t("calc_error", "错误")); trail_var.set("")
            st["acc"] = None; st["op"] = None; st["fresh"] = True
        def press_digit(d):
            d0 = disp_var.get()
            if st["fresh"] or d0 in ("0", ERR):
                disp_var.set(d); st["fresh"] = False
            elif len(d0.replace("-", "").replace(".", "")) < 16:
                disp_var.set(d0 + d)
        def press_dot():
            d0 = disp_var.get()
            if st["fresh"] or d0 == ERR:
                disp_var.set("0."); st["fresh"] = False
            elif "." not in d0:
                disp_var.set(d0 + ".")
        def press_op(o):
            if disp_var.get() == ERR: return
            v = cur()
            if st["acc"] is not None and st["op"] and not st["fresh"]:
                try: v = apply(st["acc"], st["op"], v)
                except ZeroDivisionError: show_error(); return
                disp_var.set(fmt(v))
            st["acc"] = v; st["op"] = o; st["fresh"] = True
            trail_var.set(f"{fmt(v)} {o}")
        def press_eq():
            if st["acc"] is None or not st["op"] or disp_var.get() == ERR: return
            v = cur()
            try: r = apply(st["acc"], st["op"], v)
            except ZeroDivisionError: show_error(); return
            trail_var.set(f"{fmt(st['acc'])} {st['op']} {fmt(v)} =")
            hist_add(f"{fmt(st['acc'])} {st['op']} {fmt(v)}", fmt(r))
            disp_var.set(fmt(r))
            st["acc"] = None; st["op"] = None; st["fresh"] = True
        def press_clear():
            disp_var.set("0"); trail_var.set("")
            st["acc"] = None; st["op"] = None; st["fresh"] = True
        def press_back():
            if st["fresh"]: return
            d0 = disp_var.get()[:-1]
            disp_var.set(d0 if d0 not in ("", "-") else "0")
        def press_pct():
            if disp_var.get() == ERR: return
            disp_var.set(fmt(cur() / 100)); st["fresh"] = True
        def press_neg():
            if disp_var.get() == ERR: return
            v = cur()
            if v != 0: disp_var.set(fmt(-v))
        grid = tk.Frame(card, background=W); grid.pack(padx=18, pady=(0, 20))
        layout = [
            [("C", press_clear, "CalcDanger.TButton"), ("⌫", press_back, "CalcOutline.TButton"), ("%", press_pct, "CalcOutline.TButton"), ("÷", lambda: press_op("÷"), "CalcOutline.TButton")],
            [("7", lambda: press_digit("7"), "Calc.TButton"), ("8", lambda: press_digit("8"), "Calc.TButton"), ("9", lambda: press_digit("9"), "Calc.TButton"), ("×", lambda: press_op("×"), "CalcOutline.TButton")],
            [("4", lambda: press_digit("4"), "Calc.TButton"), ("5", lambda: press_digit("5"), "Calc.TButton"), ("6", lambda: press_digit("6"), "Calc.TButton"), ("−", lambda: press_op("-"), "CalcOutline.TButton")],
            [("1", lambda: press_digit("1"), "Calc.TButton"), ("2", lambda: press_digit("2"), "Calc.TButton"), ("3", lambda: press_digit("3"), "Calc.TButton"), ("+", lambda: press_op("+"), "CalcOutline.TButton")],
            [("±", press_neg, "CalcOutline.TButton"), ("0", lambda: press_digit("0"), "Calc.TButton"), (".", press_dot, "Calc.TButton"), ("=", press_eq, "CalcAccent.TButton")],
        ]
        for r, rowbtns in enumerate(layout):
            for c, (txt, cmd, style) in enumerate(rowbtns):
                b = ttk.Button(grid, text=txt, command=cmd, style=style, width=4)
                b.grid(row=r, column=c, padx=4, pady=4, sticky="nsew")
        # ---- 计算历史 (Jane 2026-11-27): 每按一次 = 记一笔, 最新在最上; 点某条把结果填回显示屏接着算;
        # 存 BASE/calc_history.json (上限 50 条), 重启软件还在 ----
        hist_path = os.path.join(BASE, "calc_history.json")
        def hist_load():
            try:
                with open(hist_path, encoding="utf-8") as f: data = json.load(f)
                return [h for h in data if isinstance(h, dict) and "e" in h and "r" in h][:50]
            except Exception: return []
        def hist_save():
            try: _atomic_write(hist_path, json.dumps(hist, ensure_ascii=False, separators=(",", ":")))
            except Exception: pass
        hist = hist_load()
        tk.Frame(card, background=self.UI_BORDER, height=1).pack(fill="x", padx=14, pady=(2, 0))
        hhead = tk.Frame(card, background=W); hhead.pack(fill="x", padx=16, pady=(8, 2))
        tk.Label(hhead, text=self.t("calc_history", "计算历史"), font=self._ui_font(11, True), background=W, foreground=self.UI_TEXT).pack(side="left")
        clr = tk.Label(hhead, text=self.t("calc_clear_history", "清空"), font=self._ui_font(10), background=W, foreground="#5B6B7C", cursor="hand2")
        clr.pack(side="right")
        hwrap = tk.Frame(card, background=W); hwrap.pack(fill="x", padx=12, pady=(0, 12))
        hlist = tk.Listbox(hwrap, height=5, font=self._ui_font(11), background=W, foreground=self.UI_TEXT,
                           selectbackground=self.UI_SEL_BG, selectforeground=self.UI_TEXT, activestyle="none",
                           highlightthickness=0, borderwidth=0)
        hlist.pack(side="left", fill="x", expand=True)
        hsb = ttk.Scrollbar(hwrap, orient="vertical", command=hlist.yview); hsb.pack(side="right", fill="y")
        hlist.configure(yscrollcommand=hsb.set)
        def hist_refresh():
            hlist.delete(0, "end")
            if not hist:
                hlist.insert("end", self.t("calc_no_history", "暂无计算历史"))
                hlist.itemconfigure(0, foreground=self.UI_MUTED)
            else:
                for h in hist: hlist.insert("end", f"{h['e']} = {h['r']}")
        def hist_add(expr, res):
            hist.insert(0, {"e": expr, "r": res})
            del hist[50:]
            hist_save(); hist_refresh()
        def hist_pick(e):
            sel = hlist.curselection()
            if not sel or not hist: return
            h = hist[sel[0]]
            disp_var.set(h["r"]); trail_var.set("")
            st["acc"] = None; st["op"] = None; st["fresh"] = True
        hlist.bind("<<ListboxSelect>>", hist_pick)
        clr.bind("<Button-1>", lambda e: (hist.clear(), hist_save(), hist_refresh()))
        hist_refresh()
        self._calc_hist = hist  # 测试用
        self._calc_hist_list = hlist
        self._calc_disp = disp_var  # 测试/调试用
        def on_key(e):
            try:
                if self._focus_in_input(): return
                k = e.keysym
                if len(k) == 1 and k.isdigit(): press_digit(k)
                elif k in ("plus", "KP_Add"): press_op("+")
                elif k in ("minus", "KP_Subtract"): press_op("-")
                elif k in ("asterisk", "KP_Multiply"): press_op("×")
                elif k in ("slash", "KP_Divide"): press_op("÷")
                elif k in ("Return", "KP_Enter", "equal"): press_eq()
                elif k == "BackSpace": press_back()
                elif k in ("period", "KP_Decimal"): press_dot()
                elif k == "percent": press_pct()
            except Exception: pass
        self._calc_on_key = on_key

