    def _wx_icon(self, cat):
        """天气图标 (Jane 2026-11-27 世界时间美化): PIL 简笔按类别画太阳/云/雨/雪/雷电/雾等, 缓存复用"""
        cache = getattr(self, "_wx_icon_cache", None)
        if cache is None: cache = self._wx_icon_cache = {}
        if cat in cache: return cache[cat]
        from PIL import Image as _Im, ImageDraw as _IDr
        import math as _m
        S = 72
        img = _Im.new("RGBA", (S, S), (0, 0, 0, 0))
        d = _IDr.Draw(img)
        SUN, CLD, RAIN, SNOWC = "#F5A623", "#D9E2EC", "#3E7CB1", "#7FB2D9"
        def sun(cx, cy, r):
            for i in range(8):
                a = _m.radians(i * 45)
                d.line([cx + (r + 3) * _m.cos(a), cy + (r + 3) * _m.sin(a), cx + (r + 8) * _m.cos(a), cy + (r + 8) * _m.sin(a)], fill=SUN, width=3)
            d.ellipse([cx - r, cy - r, cx + r, cy + r], fill="#FFC93C", outline=SUN, width=2)
        def cloud(cx, cy, s=1.0, fill=CLD):
            d.ellipse([cx - 20 * s, cy - 6 * s, cx - 2 * s, cy + 12 * s], fill=fill)
            d.ellipse([cx - 8 * s, cy - 14 * s, cx + 12 * s, cy + 12 * s], fill=fill)
            d.ellipse([cx + 2 * s, cy - 4 * s, cx + 21 * s, cy + 12 * s], fill=fill)
            d.rectangle([cx - 20 * s, cy + 4 * s, cx + 21 * s, cy + 12 * s], fill=fill)
        def drops(xs, y=50, ln=9):
            for x in xs: d.line([x, y, x - 3, y + ln], fill=RAIN, width=3)
        def flakes(xs, y=56):
            for x in xs:
                for a in (0, 60, 120):
                    ar = _m.radians(a)
                    d.line([x - 5 * _m.cos(ar), y - 5 * _m.sin(ar), x + 5 * _m.cos(ar), y + 5 * _m.sin(ar)], fill=SNOWC, width=2)
        if cat == "clear": sun(36, 36, 15)
        elif cat == "pcloudy": sun(26, 24, 11); cloud(40, 42)
        elif cat == "cloudy": cloud(36, 34)
        elif cat == "overcast": cloud(28, 26, 0.85, "#B8C7D9"); cloud(42, 42, 0.95, "#8FA6BC")
        elif cat == "fog":
            cloud(36, 28)
            for i, yy in enumerate((50, 58, 66)): d.line([22 + (6 if i % 2 else 0), yy, 50 - (6 if i % 2 else 0), yy], fill="#9FB3C8", width=3)
        elif cat == "drizzle": cloud(36, 30); drops((26, 38, 50), y=50, ln=5)
        elif cat == "rain": cloud(36, 30); drops((26, 38, 50))
        elif cat == "shower": sun(22, 20, 9); cloud(40, 38); drops((32, 44, 54), y=56, ln=7)
        elif cat == "downpour": cloud(36, 28, 1.0, "#B8C7D9"); drops((22, 32, 42, 52), y=48, ln=12)
        elif cat == "sleet": cloud(36, 30); drops((28, 46), y=50, ln=7); flakes((37,), y=57)
        elif cat == "snow": cloud(36, 30); flakes((26, 38, 50))
        elif cat == "thunder":
            cloud(36, 28)
            d.polygon([(38, 42), (28, 58), (35, 58), (31, 68), (45, 52), (38, 52)], fill="#F7B731", outline="#E08E00")
        elif cat == "hail":
            cloud(36, 30)
            for x in (26, 38, 50): d.ellipse([x - 3, 50, x + 3, 56], fill=SNOWC)
        else: cloud(36, 34)
        photo = ImageTk.PhotoImage(img.resize((30, 30), _Im.LANCZOS))
        cache[cat] = photo
        return photo
    def _wx_tip(self, temp, desc, cat):
        """根据天气给一句温馨提醒 (Jane 2026-11-27): 恶劣天气优先, 其次极端温度, 最后按类别"""
        en = self.lang == "English"
        desc = desc or ""
        T = {
            "thunder": ("有雷电，尽量留在室内，注意安全", "Thunderstorms — stay indoors and stay safe"),
            "hail": ("有冰雹，尽量留在室内，收好阳台物品", "Hail — stay indoors and bring things in from the balcony"),
            "downpour": ("雨势很大，尽量减少外出，注意安全", "Heavy rain — head out only if you must"),
            "hot35": ("高温天气，注意防暑，多喝水", "Very hot — stay hydrated and avoid the midday sun"),
            "cold-5": ("天寒地冻，出门裹严实，注意保暖", "Freezing cold — wrap up warm before heading out"),
            "snow_big": ("雪很大，注意保暖，出行防滑", "Heavy snow — dress warm and watch your step"),
            "snow": ("下雪了，路面易滑，出行注意安全", "Snowy — roads may be slippery, take care"),
            "sleet": ("雨夹雪，路面湿滑，注意保暖", "Sleet — slippery roads, dress warm"),
            "haze": ("空气不太好，出门记得戴口罩", "Hazy air — wear a mask when you go out"),
            "fog": ("有雾，能见度低，开车注意慢行", "Foggy — low visibility, drive slowly"),
            "rain": ("下雨天，记得带伞，路上慢行", "Rainy — take an umbrella and take it slow"),
            "shower": ("阵雨说来就来，出门带把伞", "Showers can start any time — take an umbrella"),
            "drizzle": ("毛毛雨，出门带把伞更稳妥", "Light drizzle — an umbrella is a good idea"),
            "hot30": ("天气炎热，注意防晒，多喝水", "Hot day — sunscreen and plenty of water"),
            "cold5": ("天气冷，出门多穿一点", "Chilly — add a layer before you go out"),
            "clear": ("阳光正好，适合出门走走", "Lovely sunshine — a good day for a walk"),
            "pcloudy": ("天气不错，适合外出活动", "Nice weather for getting out and about"),
            "cloudy": ("多云天气，出门不用带伞", "Cloudy — no umbrella needed"),
            "overcast": ("阴天沉沉的，注意添衣保暖", "Grey and overcast — keep warm"),
        }
        def pick(k): return T[k][1 if en else 0]
        if cat == "thunder": return pick("thunder")
        if cat == "hail": return pick("hail")
        if cat == "downpour": return pick("downpour")
        if temp >= 35: return pick("hot35")
        if temp <= -5: return pick("cold-5")
        if cat == "snow": return pick("snow_big" if ("大雪" in desc or "暴雪" in desc or "Heavy" in desc) else "snow")
        if cat == "sleet": return pick("sleet")
        if cat == "fog": return pick("haze" if ("霾" in desc or "Haze" in desc or "Smok" in desc) else "fog")
        if cat == "rain": return pick("rain")
        if cat == "shower": return pick("shower")
        if cat == "drizzle": return pick("drizzle")
        if temp >= 30: return pick("hot30")
        if temp <= 5: return pick("cold5")
        if cat in T: return pick(cat)
        return ""
    def _wx_fill_row(self, row3, res):
        """把一条天气结果 (温度, 描述, 类别) 填进卡片的天气行: 图标 + 大温度 + 描述"""
        try:
            cat = res[2] if res and len(res) > 2 else "unknown"
            if res:
                row3["icon"].config(image=self._wx_icon(cat))
                row3["temp"].config(text=f"{res[0]}°C")
                row3["desc"].config(text=res[1] or "")
                row3["tip"].config(text=self._wx_tip(res[0], res[1], cat))
            else:
                row3["temp"].config(text="")
                row3["desc"].config(text=self.t("clk_wx_na", "天气暂不可用"))
                row3["tip"].config(text="")
        except Exception: pass
    def _show_clock_panel(self):
        self._texttrans_on_hide()
        if getattr(self, "_clock_panel", None) is None:
            self._build_clock_panel()
        try: self._body.pack_forget()
        except Exception: pass
        for attr in ("_ai_panel", "_fx_panel", "_calc_panel", "_phrases_panel", "_dl_panel"):
            p = getattr(self, attr, None)
            if p is not None:
                try: p.pack_forget()
                except Exception: pass
        self._ai_view_on = False
        self._wheel_bind(False)
        self._calc_bind(False)
        self._forget_aux_panels()
        self._clock_panel.pack(fill="both", expand=True, before=self._status_sep)
        aid = getattr(self, "_clock_after", None)
        if aid:
            try: self.after_cancel(aid)
            except Exception: pass
        self._clock_gen = getattr(self, "_clock_gen", 0) + 1  # 每次打开递增代号: 旧计时链靠代号自杀, 防改城市重建面板后多条链叠加空转
        gen = self._clock_gen
        self._clock_after = self.after(50, lambda: self._clock_tick(gen))  # 等面板真正显示出来再启表 (刚 pack 完 winfo_ismapped 还是 False, 立刻 tick 会误判隐藏而停摆)
        self._maybe_fetch_weather()

    def _daypart(self, hour):
        """对方作息时段 (Jane 2026-11-27: 和外国人聊天, 卡片上标对方现在白天还是凌晨, 免得打扰):
        返回 (文案, 颜色): 白天绿 (适宜聊天) / 晚上橙 (别太晚) / 凌晨红 (在睡觉别打扰)"""
        if 7 <= hour < 12: return (self.t("clk_part_morning", "上午 · 适宜聊天"), "#1F9D66")
        if 12 <= hour < 18: return (self.t("clk_part_afternoon", "下午 · 适宜聊天"), "#1F9D66")
        if 18 <= hour < 23: return (self.t("clk_part_evening", "晚上 · 可以聊, 别太晚"), "#B26A00")
        if hour == 23: return (self.t("clk_part_night", "夜里 · 对方快休息了"), "#B26A00")
        return (self.t("clk_part_late", "凌晨 · 对方在睡觉, 别打扰"), "#D64545")

    def _clock_convert(self):
        """约时间换算 (Jane 2026-11-27: 世界时间面板底部): 我的时间 -> 对方城市的当地时间,
        并生成一句可直接发送的双语确认句; 对方那是凌晨时红字提醒慎选"""
        from datetime import datetime
        try:
            dstr = self._conv_date.get().strip(); tstr = self._conv_time.get().strip()
            dt = datetime.strptime(dstr + " " + tstr, "%Y-%m-%d %H:%M")
        except Exception:
            self._conv_result.set(self.t("clk_conv_bad", "格式不对: 日期用 2026-11-28, 时间用 15:00"))
            self._conv_warn.set(""); self._conv_msg = ""
            return
        tz = getattr(self, "_conv_tzs", {}).get(self._conv_city_var.get())
        if tz is None:
            self._conv_result.set(self.t("clk_conv_bad", "格式不对: 日期用 2026-11-28, 时间用 15:00")); self._conv_msg = ""
            return
        mine = dt.astimezone()  # naive 按本地时间解释, astimezone 会按目标日期当天的规则取偏移 (2026-11-27 审查: 旧写法拿今天的固定偏移套任意日期, 跨夏令时区间会差 1 小时)
        theirs = mine.astimezone(tz)
        wd_en = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"]
        wd_zh = ["周一", "周二", "周三", "周四", "周五", "周六", "周日"]
        my_en = f"{mine.strftime('%b %d')}, {mine.strftime('%H:%M')} ({wd_en[mine.weekday()]})"
        th_en = f"{theirs.strftime('%b %d')}, {theirs.strftime('%H:%M')} ({wd_en[theirs.weekday()]})"
        my_zh = f"{mine.month}月{mine.day}日 {mine.strftime('%H:%M')} ({wd_zh[mine.weekday()]})"
        th_zh = f"{theirs.month}月{theirs.day}日 {theirs.strftime('%H:%M')} ({wd_zh[theirs.weekday()]})"
        city = self._conv_city_var.get()
        self._conv_result.set(f"{self.t('clk_conv_theirs', '对方时间')} ({city}): {th_zh}")
        self._conv_msg_en = f"Hi! How about we talk at {th_en} your time? (That's {my_en} my time.)"
        self._conv_msg_zh = f"你好, 我们约在你那边 {th_zh} 通话可以吗? (我这边是 {my_zh})"
        self._conv_msg = self._conv_msg_en + "\n" + self._conv_msg_zh
        if 0 <= theirs.hour < 7:
            self._conv_warn.set(self.t("clk_conv_warn", "提醒: 对方那是凌晨, 建议换个时间"))
        else:
            self._conv_warn.set("")

