        self._ai_think_var = tk.BooleanVar(value=(self.cfg.get("AI", "Thinking", fallback="0") or "0").strip() == "1")  # 深度思考开关: 挂在输入框 + 菜单里 (仿 GPT), 保存见 _save_ai_thinking
        busy = {"on": False}
