                # 豆包式 (Jane 2026-11-27 改主意, 照豆包截图): 图标行在气泡内部、文字下方一条细线隔开;
                # 蓝色小方片依次 复制/朗读/点赞/点踩/分享, 重新生成是右端一个刷新方片 (只有最新一条回复有)
                wrap = tk.Frame(row, background=BUB_AI); wrap.pack(anchor="w")
                bubble(wrap, text, BUB_AI, self.UI_TEXT).pack(anchor="w")
